      probe = busy_probe();
      if ((g_active.busy &&
           clock_systime_ticks() - g_active.started >= MB_TIMEOUT) ||
          (probe != NULL &&
           clock_systime_ticks() - probe->started >= MB_TIMEOUT))
        {
          g_stats.timeout++;
          if (probe != NULL)
            {
              probe->quarantine = true;
              complete_transaction(probe, NULL, -ETIMEDOUT);
              g_stats.probe_fail++;
              set_link_state(BK7258_MB_LINK_DOWN);
