    AVDK_GOTO_ON_FALSE(ret == AVDK_ERR_OK, AVDK_ERR_INVAL, error, TAG, "init dma failed");

    controller->driver = driver_config;

    controller->state = JPEG_ENCODE_STATE_OPENED;

    return AVDK_ERR_OK;

