/****************************************************************************
 * board/beken/chips/bk7258/bk7258_flash_client.c
 *
 * Flash access for the AP, by asking the CP to do it.
 *
 * Why this exists
 * ---------------
 * The AP had no writable persistent storage at all, which is why every API
 * key and Wi-Fi credential had to be either compiled in or re-typed after
 * each reset.  Flash is there -- the partition table even reserves
 * `easyflash_ap`, 8KB at 0x007FC000, read/write/execute-disabled, for this
 * core -- but the AP must not program it directly: both cores execute XIP
 * from the same part, so an erase started by one stalls the other's
 * instruction fetch.  That is exactly why the vendor made flash a service:
 * cp/middleware/driver/flash/flash_server.c serves requests that
 * ap/middleware/driver/flash/flash_client.c sends over the mailbox.
 *
 * And the CP firmware already on this board runs that server:
 * projects/app_ab/build/.../bk7258/config/sdkconfig.h has CONFIG_FLASH_MB=1
 * and flash_server.c.obj is in its build tree.  So no CP change is needed --
 * only a client, which is what this file is.
 *
 * Protocol (mb_ipc sockets, ap/middleware/driver/mailbox/mb_ipc.c)
 * ---------------------------------------------------------------
 * Frames ride logical channel 0x11 out (CP0_MB_CHNL_IPC) and 0x41 back.  The
 * 16-byte frame the vendor calls mb_chnl_cmd_t is byte-for-byte the wire
 * message this port already sends on the other channels; only the meaning of
 * the three parameter words differs:
 *
 *   header          hdr: cmd, state, ctrl, seq, channel
 *   payload_address param1: dst_port:6 dst_cpu:2 | src_port:6 src_cpu:2 |
 *                           tag:8 | api_impl_status:4 route_status:4
 *   payload_length  param2 low half: cmd_data_len
 *   flags           param2 bits 16-23: cmd_data_crc8
 *   crc8            param2 bits 24-31: user_cmd (0xFF means none)
 *   reserved        param3: cmd_data_buff, a pointer both cores can read
 *
 * hdr.cmd is MB_IPC_CONNECT_CMD (0), MB_IPC_DISCONNECT_CMD (1) or
 * MB_IPC_SEND_CMD (2); a response is the same value with 0x80 set.  Ports:
 * the flash server is CPU0 port 1, this client is CPU1 port 16
 * (include/driver/mb_ipc_port_cfg.h).
 *
 * Every request to the server is answered by one frame, and the server
 * expects a receive for each of its sends -- flash_client.c's read path even
 * ends with a bare recv it calls "just a handshake".  This client keeps the
 * same shape.
 *
 * Read returns the data in the *server's* buffer (it hands back a pointer in
 * cmd.buff plus a CRC-32 over the bytes), so the copy happens here.  Write
 * and erase carry the caller's buffer the same way.
 *
 * Bounded waits everywhere, deliberately: if the AP stops answering the CP's
 * heartbeat for CONFIG_INT_WDT_PERIOD_MS (8s) the CP tears the console
 * bridge down and asserts, resetting the whole part with no output from this
 * side (arm_lowputc() is itself a mailbox tunnel).  Blocking forever on a
 * silent server would look exactly like that bug.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/semaphore.h>

#include "hardware/bk7258_mbox.h"
#include "bk7258_flash_client.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* mb_ipc command ids and the response flag (include/driver/mb_ipc.h). */

#define IPC_CMD_CONNECT        0u
#define IPC_CMD_DISCONNECT     1u
#define IPC_CMD_SEND           2u
#define IPC_RSP_FLAG           0x80u
#define IPC_CMD_MASK           0x7fu

#define IPC_USER_CMD_NONE      0xffu

/* Ports (include/driver/mb_ipc_port_cfg.h): server ids are cpu<<6 | port. */

#define IPC_FLASH_SERVER_CPU   0u
#define IPC_FLASH_SERVER_PORT  1u
#define IPC_FLASH_CLIENT_CPU   1u
#define IPC_FLASH_CLIENT_PORT  16u

/* Flash service commands (ap/middleware/driver/flash/flash_ipc.h). */

#define FLASH_CMD_ERASE_SECTOR 0u
#define FLASH_CMD_READ         3u
#define FLASH_CMD_READ_DONE    4u
#define FLASH_CMD_WRITE        5u

/* The server chunks transfers; flash_ipc.h fixes both at 512 bytes. */

#define FLASH_IPC_CHUNK        0x200u

#define FLASH_OP_TIMEOUT_MS    600u
#define FLASH_CONNECT_TIMEOUT_MS 1000u

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* The descriptor the flash service exchanges (flash_ipc.h flash_cmd_t).
 * Layout matters: it crosses cores.
 */

struct flash_ipc_cmd_s
{
  uint32_t part_addr;       /* part_id:8 then addr:24 */
  FAR uint8_t *buff;
  uint16_t len;
  int16_t ret_status;
  uint32_t crc;
};

static_assert(sizeof(struct flash_ipc_cmd_s) == 16,
              "flash_cmd_t ABI size");

struct flash_client_s
{
  mutex_t lock;             /* One request at a time */
  sem_t done;               /* Posted by the RX callback */
  bool connected;
  uint8_t tag;
  volatile uint8_t rsp_cmd;      /* hdr.cmd of the frame received */
  volatile uint8_t rsp_user_cmd; /* user_cmd of the frame received */
  volatile uint8_t rsp_status;   /* api_impl_status | route_status */
  volatile uint16_t rsp_len;
  FAR uint8_t *volatile rsp_buff;
  struct flash_ipc_cmd_s request;  /* Kept alive while the CP reads it */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct flash_client_s g_flash =
{
  .lock = NXMUTEX_INITIALIZER,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* CRC-32 over the bytes the server reports, same polynomial the vendor's
 * calc_crc32() uses (reflected 0xedb88320, init and final xor 0xffffffff).
 * Used to check a read rather than trust it; a mismatch means the descriptor
 * and the data disagree, which is the failure worth catching.
 */

static uint32_t flash_crc32(FAR const uint8_t *data, size_t len)
{
  uint32_t crc = 0xffffffffu;
  size_t i;
  int bit;

  for (i = 0; i < len; i++)
    {
      crc ^= data[i];
      for (bit = 0; bit < 8; bit++)
        {
          crc = (crc >> 1) ^ (0xedb88320u & (~(crc & 1u) + 1u));
        }
    }

  return ~crc;
}

static uint32_t flash_ipc_param1(uint8_t tag)
{
  uint32_t dst = IPC_FLASH_SERVER_PORT | (IPC_FLASH_SERVER_CPU << 6);
  uint32_t src = IPC_FLASH_CLIENT_PORT | (IPC_FLASH_CLIENT_CPU << 6);

  return dst | (src << 8) | ((uint32_t)tag << 16);
}

/****************************************************************************
 * Name: flash_ipc_rx
 *
 * Description:
 *   One frame arrived from the CP on the IPC channel.  Interrupt context:
 *   record what came in and wake the requester, nothing else.
 *
 ****************************************************************************/

static int flash_ipc_rx(FAR const struct bk7258_mb_wire_message *message,
                        FAR uint8_t *ack_flags, FAR void *arg)
{
  UNUSED(arg);

  if (ack_flags != NULL)
    {
      *ack_flags = 0;
    }

  g_flash.rsp_cmd = bk7258_mb_header_cmd(message);
  g_flash.rsp_user_cmd = message->crc8;
  g_flash.rsp_status = (uint8_t)(message->payload_address >> 24);
  g_flash.rsp_len = message->payload_length;
  g_flash.rsp_buff = (FAR uint8_t *)(uintptr_t)message->reserved;

  nxsem_post(&g_flash.done);
  return OK;
}

/****************************************************************************
 * Name: flash_ipc_xfer
 *
 * Description:
 *   Send one frame and wait for the single frame that answers it.  Returns
 *   OK, or -ETIMEDOUT if the CP said nothing in time, or -EREMOTEIO if it
 *   answered with a router or API error.
 *
 ****************************************************************************/

static int flash_ipc_xfer(uint8_t cmd, uint8_t user_cmd,
                          FAR void *data, uint16_t len,
                          unsigned int timeout_ms)
{
  struct bk7258_mb_wire_message message;
  int ret;

  memset(&message, 0, sizeof(message));
  message.header = cmd;
  message.payload_address = flash_ipc_param1(g_flash.tag++);
  message.payload_length = len;
  message.flags = 0;                       /* cmd_data_crc8, unused here */
  message.crc8 = user_cmd;                 /* param2 bits 24-31 */
  message.reserved = (uint32_t)(uintptr_t)data;

  /* Drain a stale post, if any: a previous timeout may have left one. */

  while (nxsem_trywait(&g_flash.done) == OK)
    {
    }

  g_flash.rsp_cmd = IPC_USER_CMD_NONE;

  ret = bk7258_mailbox_send_wire(BK7258_MB_CHAN_IPC_TX, &message, NULL, NULL);
  if (ret < 0)
    {
      return ret;
    }

  ret = nxsem_tickwait_uninterruptible(&g_flash.done,
                                       MSEC2TICK(timeout_ms));
  if (ret < 0)
    {
      return -ETIMEDOUT;
    }

  if (g_flash.rsp_status != 0)
    {
      return -EREMOTEIO;
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int bk7258_flash_client_init(void)
{
  int ret;

  if (g_flash.connected)
    {
      return OK;
    }

  nxsem_init(&g_flash.done, 0, 0);

  ret = bk7258_mailbox_register_rx(BK7258_MB_CHAN_IPC_RX, flash_ipc_rx,
                                   NULL);
  if (ret < 0)
    {
      printf("flash: cannot take the IPC channel: %d\n", ret);
      return ret;
    }

  ret = flash_ipc_xfer(IPC_CMD_CONNECT, IPC_USER_CMD_NONE, NULL, 0,
                       FLASH_CONNECT_TIMEOUT_MS);
  if (ret < 0)
    {
      printf("flash: no answer from the CP flash server: %d\n", ret);
      return ret;
    }

  if ((g_flash.rsp_cmd & IPC_CMD_MASK) != IPC_CMD_CONNECT ||
      (g_flash.rsp_cmd & IPC_RSP_FLAG) == 0)
    {
      printf("flash: unexpected answer to connect: cmd=0x%02x\n",
             g_flash.rsp_cmd);
      return -EPROTO;
    }

  g_flash.connected = true;
  printf("flash: connected to the CP flash server (cpu%u port%u)\n",
         IPC_FLASH_SERVER_CPU, IPC_FLASH_SERVER_PORT);
  return OK;
}

bool bk7258_flash_client_ready(void)
{
  return g_flash.connected;
}

int bk7258_flash_read(uint32_t address, FAR void *buffer, size_t len)
{
  FAR uint8_t *out = buffer;
  int ret = OK;

  if (!g_flash.connected || buffer == NULL || len == 0)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_flash.lock);

  while (len > 0)
    {
      size_t chunk = len > FLASH_IPC_CHUNK ? FLASH_IPC_CHUNK : len;

      memset(&g_flash.request, 0, sizeof(g_flash.request));
      g_flash.request.part_addr = address & 0x00ffffffu;
      g_flash.request.len = (uint16_t)chunk;

      ret = flash_ipc_xfer(IPC_CMD_SEND, FLASH_CMD_READ, &g_flash.request,
                           sizeof(g_flash.request), FLASH_OP_TIMEOUT_MS);
      if (ret < 0)
        {
          break;
        }

      if (g_flash.rsp_user_cmd != FLASH_CMD_READ ||
          g_flash.rsp_len != sizeof(struct flash_ipc_cmd_s) ||
          g_flash.rsp_buff == NULL)
        {
          ret = -EPROTO;
          break;
        }

      {
        FAR const struct flash_ipc_cmd_s *rsp =
          (FAR const struct flash_ipc_cmd_s *)g_flash.rsp_buff;

        if (rsp->ret_status != 0 || rsp->len != chunk || rsp->buff == NULL)
          {
            ret = -EIO;
            break;
          }

        memcpy(out, rsp->buff, chunk);

        if (flash_crc32(out, chunk) != rsp->crc)
          {
            ret = -EBADMSG;
            break;
          }
      }

      /* The server waits for this before releasing its buffer, and for one
       * receive per send of its own -- see flash_client.c's read path.
       */

      (void)flash_ipc_xfer(IPC_CMD_SEND, FLASH_CMD_READ_DONE,
                           &g_flash.request, sizeof(g_flash.request),
                           FLASH_OP_TIMEOUT_MS);

      out += chunk;
      address += chunk;
      len -= chunk;
    }

  nxmutex_unlock(&g_flash.lock);
  return ret;
}

int bk7258_flash_erase_sector(uint32_t address)
{
  int ret;

  if (!g_flash.connected)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_flash.lock);

  memset(&g_flash.request, 0, sizeof(g_flash.request));
  g_flash.request.part_addr = address & 0x00ffffffu;

  ret = flash_ipc_xfer(IPC_CMD_SEND, FLASH_CMD_ERASE_SECTOR,
                       &g_flash.request, sizeof(g_flash.request),
                       FLASH_OP_TIMEOUT_MS);
  if (ret == OK)
    {
      FAR const struct flash_ipc_cmd_s *rsp =
        (FAR const struct flash_ipc_cmd_s *)g_flash.rsp_buff;

      if (g_flash.rsp_user_cmd != FLASH_CMD_ERASE_SECTOR)
        {
          ret = -EPROTO;
        }
      else if (rsp == NULL || rsp->ret_status != 0)
        {
          ret = -EIO;
        }
    }

  nxmutex_unlock(&g_flash.lock);
  return ret;
}

int bk7258_flash_write(uint32_t address, FAR const void *buffer, size_t len)
{
  FAR const uint8_t *in = buffer;
  int ret = OK;

  if (!g_flash.connected || buffer == NULL || len == 0)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_flash.lock);

  while (len > 0)
    {
      size_t chunk = len > FLASH_IPC_CHUNK ? FLASH_IPC_CHUNK : len;

      memset(&g_flash.request, 0, sizeof(g_flash.request));
      g_flash.request.part_addr = address & 0x00ffffffu;
      g_flash.request.buff = (FAR uint8_t *)in;
      g_flash.request.len = (uint16_t)chunk;
      g_flash.request.crc = flash_crc32(in, chunk);

      ret = flash_ipc_xfer(IPC_CMD_SEND, FLASH_CMD_WRITE, &g_flash.request,
                           sizeof(g_flash.request), FLASH_OP_TIMEOUT_MS);
      if (ret < 0)
        {
          break;
        }

      {
        FAR const struct flash_ipc_cmd_s *rsp =
          (FAR const struct flash_ipc_cmd_s *)g_flash.rsp_buff;

        if (g_flash.rsp_user_cmd != FLASH_CMD_WRITE)
          {
            ret = -EPROTO;
            break;
          }

        if (rsp == NULL || rsp->ret_status != 0)
          {
            ret = -EIO;
            break;
          }
      }

      in += chunk;
      address += chunk;
      len -= chunk;
    }

  nxmutex_unlock(&g_flash.lock);
  return ret;
}

/****************************************************************************
 * board/beken/chips/bk7258/bk7258_kvdb.c
 *
 * A small key-value store in the AP's own flash partition, so configuration
 * is typed once instead of compiled in or re-entered after every reset.
 *
 * What it replaces
 * ----------------
 * Two things were being hard-coded, both of which this removes the need for:
 *
 *   - the MiMo API key and endpoint, through
 *     packages/ai_agent/include/agent_secrets.h -- a header copied into a
 *     *public* repository and compiled into the image, so the key ended up in
 *     the .bin and the firmware could not be shared.
 *   - Wi-Fi credentials, re-typed with `wapi psk`/`wapi essid` after each
 *     reset because /mnt is a PSRAM ramdisk and loses everything.
 *
 * Layout
 * ------
 * One 4KB sector holds the whole store, rewritten as a unit:
 *
 *   magic "VKVDB\0\0\0" | version | count | crc32 of the record area
 *   records: key length, value length, key bytes, value bytes, repeated
 *
 * Rewriting everything on each set is the right trade here.  The store is
 * well under 1KB, a set happens when a human types one, and the alternative
 * -- appending records and compacting later -- is more code and more failure
 * modes for no gain at this size.  The second sector of the partition is
 * deliberately left alone: it is where a future A/B scheme would go, and
 * leaving it erased means a half-written sector can never look valid.
 *
 * A store whose CRC does not match is treated as empty rather than repaired.
 * Configuration is cheap to retype; guessing at damaged bytes is not.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <nuttx/mutex.h>

#include "bk7258_flash_client.h"
#include "bk7258_kvdb.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define KVDB_MAGIC        "VKVDB\0\0"
#define KVDB_MAGIC_LEN    8u
#define KVDB_VERSION      1u
#define KVDB_SECTOR       BK7258_FLASH_AP_ENV_BASE
#define KVDB_CAPACITY     BK7258_FLASH_SECTOR_SIZE

/****************************************************************************
 * Private Types
 ****************************************************************************/

begin_packed_struct struct kvdb_header_s
{
  char     magic[KVDB_MAGIC_LEN];
  uint32_t version;
  uint32_t count;
  uint32_t bytes;      /* Record area length */
  uint32_t crc;        /* CRC-32 over the record area */
} end_packed_struct;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static mutex_t g_kvdb_lock = NXMUTEX_INITIALIZER;

/* The whole store, mirrored in RAM.  4KB out of the system heap, which
 * reaches PSRAM on this board; keeping it resident is what makes get() free
 * and avoids a flash round trip on the boot path.
 */

static FAR uint8_t *g_kvdb_image;
static bool g_kvdb_loaded;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint32_t kvdb_crc32(FAR const uint8_t *data, size_t len)
{
  uint32_t crc = 0xffffffffu;
  size_t i;
  int bit;

  for (i = 0; i < len; i++)
    {
      crc ^= data[i];
      for (bit = 0; bit < 8; bit++)
        {
          crc = (crc >> 1) ^ (0xedb88320u & (~(crc & 1u) + 1u));
        }
    }

  return ~crc;
}

static FAR struct kvdb_header_s *kvdb_hdr(void)
{
  return (FAR struct kvdb_header_s *)g_kvdb_image;
}

static FAR uint8_t *kvdb_records(void)
{
  return g_kvdb_image + sizeof(struct kvdb_header_s);
}

static void kvdb_reset_image(void)
{
  FAR struct kvdb_header_s *hdr = kvdb_hdr();

  memset(g_kvdb_image, 0, KVDB_CAPACITY);
  memcpy(hdr->magic, KVDB_MAGIC, KVDB_MAGIC_LEN);
  hdr->version = KVDB_VERSION;
  hdr->count = 0;
  hdr->bytes = 0;
  hdr->crc = kvdb_crc32(kvdb_records(), 0);
}

/* Walk the records, returning the offset of key or -1.  Record format is
 * two bytes of key length, two of value length, then the bytes; both are
 * stored without terminators so a value may contain anything.
 */

static ssize_t kvdb_find(FAR const char *key, FAR uint16_t *vlen)
{
  FAR uint8_t *rec = kvdb_records();
  uint32_t used = kvdb_hdr()->bytes;
  size_t klen = strlen(key);
  size_t off = 0;

  while (off + 4u <= used)
    {
      uint16_t rk = (uint16_t)(rec[off] | (rec[off + 1] << 8));
      uint16_t rv = (uint16_t)(rec[off + 2] | (rec[off + 3] << 8));

      if (off + 4u + rk + rv > used)
        {
          break;
        }

      if (rk == klen && memcmp(&rec[off + 4], key, klen) == 0)
        {
          if (vlen != NULL)
            {
              *vlen = rv;
            }

          return (ssize_t)off;
        }

      off += 4u + rk + rv;
    }

  return -1;
}

static int kvdb_flush(void)
{
  FAR struct kvdb_header_s *hdr = kvdb_hdr();
  int ret;

  hdr->crc = kvdb_crc32(kvdb_records(), hdr->bytes);

  ret = bk7258_flash_erase_sector(KVDB_SECTOR);
  if (ret < 0)
    {
      return ret;
    }

  /* Only the part in use is written back.  The rest of the sector stays
   * erased, which costs nothing and makes a truncated write obvious.
   */

  return bk7258_flash_write(KVDB_SECTOR, g_kvdb_image,
                            sizeof(struct kvdb_header_s) + hdr->bytes);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int bk7258_kvdb_init(void)
{
  FAR struct kvdb_header_s *hdr;
  int ret;

  nxmutex_lock(&g_kvdb_lock);

  if (g_kvdb_loaded)
    {
      nxmutex_unlock(&g_kvdb_lock);
      return OK;
    }

  if (g_kvdb_image == NULL)
    {
      g_kvdb_image = malloc(KVDB_CAPACITY);
      if (g_kvdb_image == NULL)
        {
          nxmutex_unlock(&g_kvdb_lock);
          return -ENOMEM;
        }
    }

  ret = bk7258_flash_client_init();
  if (ret < 0)
    {
      /* No flash service: start empty and in memory only, so a board whose
       * CP does not serve flash still runs -- it just forgets on reset, which
       * is the behaviour everything had before this existed.
       */

      kvdb_reset_image();
      g_kvdb_loaded = true;
      nxmutex_unlock(&g_kvdb_lock);
      printf("kvdb: no flash service, running in memory only\n");
      return ret;
    }

  ret = bk7258_flash_read(KVDB_SECTOR, g_kvdb_image, KVDB_CAPACITY);
  if (ret < 0)
    {
      kvdb_reset_image();
      g_kvdb_loaded = true;
      nxmutex_unlock(&g_kvdb_lock);
      printf("kvdb: read failed (%d), starting empty\n", ret);
      return ret;
    }

  hdr = kvdb_hdr();

  if (memcmp(hdr->magic, KVDB_MAGIC, KVDB_MAGIC_LEN) != 0 ||
      hdr->version != KVDB_VERSION ||
      hdr->bytes > KVDB_CAPACITY - sizeof(struct kvdb_header_s) ||
      hdr->crc != kvdb_crc32(kvdb_records(), hdr->bytes))
    {
      printf("kvdb: no valid store at 0x%08x, starting empty\n",
             (unsigned int)KVDB_SECTOR);
      kvdb_reset_image();
    }
  else
    {
      printf("kvdb: %lu key(s) loaded from flash, %lu bytes used\n",
             (unsigned long)hdr->count, (unsigned long)hdr->bytes);
    }

  g_kvdb_loaded = true;
  nxmutex_unlock(&g_kvdb_lock);
  return OK;
}

int bk7258_kvdb_get(FAR const char *key, FAR char *value, size_t size)
{
  uint16_t vlen = 0;
  ssize_t off;
  int ret;

  if (key == NULL || value == NULL || size == 0 || !g_kvdb_loaded)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_kvdb_lock);

  off = kvdb_find(key, &vlen);
  if (off < 0)
    {
      ret = -ENOENT;
    }
  else if ((size_t)vlen + 1u > size)
    {
      ret = -E2BIG;
    }
  else
    {
      FAR uint8_t *rec = kvdb_records() + off;

      memcpy(value, &rec[4 + strlen(key)], vlen);
      value[vlen] = '\0';
      ret = (int)vlen;
    }

  nxmutex_unlock(&g_kvdb_lock);
  return ret;
}

int bk7258_kvdb_set(FAR const char *key, FAR const char *value)
{
  FAR struct kvdb_header_s *hdr;
  size_t klen;
  size_t vlen;
  ssize_t off;
  int ret;

  if (key == NULL || value == NULL || !g_kvdb_loaded)
    {
      return -EINVAL;
    }

  klen = strlen(key);
  vlen = strlen(value);

  if (klen == 0 || klen > 64 || vlen > 512)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_kvdb_lock);
  hdr = kvdb_hdr();

  /* Replace by removing then appending: values change length, and moving the
   * tail once is simpler than patching in place and cheaper to reason about.
   */

  off = kvdb_find(key, NULL);
  if (off >= 0)
    {
      FAR uint8_t *rec = kvdb_records() + off;
      uint16_t rk = (uint16_t)(rec[0] | (rec[1] << 8));
      uint16_t rv = (uint16_t)(rec[2] | (rec[3] << 8));
      size_t rlen = 4u + rk + rv;

      memmove(rec, rec + rlen, hdr->bytes - off - rlen);
      hdr->bytes -= rlen;
      hdr->count--;
    }

  if (sizeof(struct kvdb_header_s) + hdr->bytes + 4u + klen + vlen >
      KVDB_CAPACITY)
    {
      nxmutex_unlock(&g_kvdb_lock);
      return -ENOSPC;
    }

  {
    FAR uint8_t *rec = kvdb_records() + hdr->bytes;

    rec[0] = (uint8_t)(klen & 0xff);
    rec[1] = (uint8_t)(klen >> 8);
    rec[2] = (uint8_t)(vlen & 0xff);
    rec[3] = (uint8_t)(vlen >> 8);
    memcpy(&rec[4], key, klen);
    memcpy(&rec[4 + klen], value, vlen);

    hdr->bytes += 4u + klen + vlen;
    hdr->count++;
  }

  ret = kvdb_flush();

  nxmutex_unlock(&g_kvdb_lock);
  return ret;
}

int bk7258_kvdb_del(FAR const char *key)
{
  FAR struct kvdb_header_s *hdr;
  ssize_t off;
  int ret;

  if (key == NULL || !g_kvdb_loaded)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_kvdb_lock);
  hdr = kvdb_hdr();

  off = kvdb_find(key, NULL);
  if (off < 0)
    {
      nxmutex_unlock(&g_kvdb_lock);
      return -ENOENT;
    }

  {
    FAR uint8_t *rec = kvdb_records() + off;
    uint16_t rk = (uint16_t)(rec[0] | (rec[1] << 8));
    uint16_t rv = (uint16_t)(rec[2] | (rec[3] << 8));
    size_t rlen = 4u + rk + rv;

    memmove(rec, rec + rlen, hdr->bytes - off - rlen);
    hdr->bytes -= rlen;
    hdr->count--;
  }

  ret = kvdb_flush();

  nxmutex_unlock(&g_kvdb_lock);
  return ret;
}

int bk7258_kvdb_foreach(bk7258_kvdb_cb_t callback, FAR void *arg)
{
  FAR uint8_t *rec;
  uint32_t used;
  size_t off = 0;
  int n = 0;

  if (callback == NULL || !g_kvdb_loaded)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_kvdb_lock);
  rec = kvdb_records();
  used = kvdb_hdr()->bytes;

  while (off + 4u <= used)
    {
      uint16_t rk = (uint16_t)(rec[off] | (rec[off + 1] << 8));
      uint16_t rv = (uint16_t)(rec[off + 2] | (rec[off + 3] << 8));
      char key[65];
      char value[513];

      if (off + 4u + rk + rv > used || rk > 64 || rv > 512)
        {
          break;
        }

      memcpy(key, &rec[off + 4], rk);
      key[rk] = '\0';
      memcpy(value, &rec[off + 4 + rk], rv);
      value[rv] = '\0';

      callback(key, value, arg);
      n++;

      off += 4u + rk + rv;
    }

  nxmutex_unlock(&g_kvdb_lock);
  return n;
}

/****************************************************************************
 * app/kvdb_tool/kvdb_tool_main.c
 *
 * `kvdb` -- read and write the configuration that survives a reset.
 *
 * The store lives in the AP's own flash partition and is written through the
 * CP's flash service; see board/beken/chips/bk7258/bk7258_kvdb.c.  What this
 * command exists for is the developer loop: type the API key and the Wi-Fi
 * passphrase once, on the board, and never again -- instead of compiling the
 * key into the image through packages/ai_agent/include/agent_secrets.h (a
 * public repository, and the key ends up in the .bin) or re-entering the
 * Wi-Fi credentials after every reset (/mnt is a PSRAM ramdisk).
 *
 * Usage:
 *   kvdb                       list keys, secrets masked
 *   kvdb list [--raw]          same; --raw prints secrets in full
 *   kvdb get <key> [--raw]     print one value
 *   kvdb set <key> <value>     write and persist
 *   kvdb del <key>             remove and persist
 *
 * Anything whose key ends in ".key" or ".psk" is masked unless --raw is
 * given, because these values otherwise end up in serial logs and in the AI
 * coding logs this project has to submit.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "bk7258_kvdb.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void kvdb_usage(void)
{
  printf("Usage: kvdb [list|get|set|del] ...\n"
         "  kvdb                    list keys (secrets masked)\n"
         "  kvdb list [--raw]       same, --raw shows secrets\n"
         "  kvdb get <key> [--raw]  print one value\n"
         "  kvdb set <key> <value>  write and persist across reset\n"
         "  kvdb del <key>          remove and persist\n"
         "\n"
         "Keys the rest of the system reads:\n"
         "  llm.key llm.host llm.model wifi.ssid wifi.psk\n");
}

static bool kvdb_is_secret(const char *key)
{
  size_t len = strlen(key);

  return (len >= 4 && strcmp(key + len - 4, ".key") == 0) ||
         (len >= 4 && strcmp(key + len - 4, ".psk") == 0);
}

/* Show enough to recognise which key is loaded, not enough to use it. */

static void kvdb_print_value(const char *key, const char *value, bool raw)
{
  size_t len = strlen(value);

  if (raw || !kvdb_is_secret(key) || len == 0)
    {
      printf("%s = %s\n", key, value);
    }
  else if (len <= 8)
    {
      printf("%s = **** (%zu bytes)\n", key, len);
    }
  else
    {
      printf("%s = %.4s...%s (%zu bytes)\n", key, value, value + len - 4,
             len);
    }
}

static void kvdb_list_one(const char *key, const char *value, void *arg)
{
  kvdb_print_value(key, value, *(bool *)arg);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  bool raw = false;
  int i;
  int ret;

  for (i = 1; i < argc; i++)
    {
      if (strcmp(argv[i], "--raw") == 0)
        {
          raw = true;
        }
    }

  ret = bk7258_kvdb_init();
  if (ret < 0)
    {
      /* Not fatal: the store still answers for this boot, it just will not
       * survive a reset.  Say so rather than pretending it persisted.
       */

      printf("kvdb: flash unavailable (%d) -- changes last until reset\n",
             ret);
    }

  if (argc < 2 || strcmp(argv[1], "list") == 0)
    {
      ret = bk7258_kvdb_foreach(kvdb_list_one, &raw);
      if (ret == 0)
        {
          printf("kvdb: empty\n");
        }
      else if (ret < 0)
        {
          printf("kvdb: list failed: %d\n", ret);
          return EXIT_FAILURE;
        }

      return EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "get") == 0 && argc >= 3)
    {
      char value[513];

      ret = bk7258_kvdb_get(argv[2], value, sizeof(value));
      if (ret == -ENOENT)
        {
          printf("kvdb: %s is not set\n", argv[2]);
          return EXIT_FAILURE;
        }

      if (ret < 0)
        {
          printf("kvdb: get %s failed: %d\n", argv[2], ret);
          return EXIT_FAILURE;
        }

      kvdb_print_value(argv[2], value, raw);
      return EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "set") == 0 && argc >= 4)
    {
      ret = bk7258_kvdb_set(argv[2], argv[3]);
      if (ret < 0)
        {
          printf("kvdb: set %s failed: %d\n", argv[2], ret);
          return EXIT_FAILURE;
        }

      printf("kvdb: %s written to flash\n", argv[2]);
      return EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "del") == 0 && argc >= 3)
    {
      ret = bk7258_kvdb_del(argv[2]);
      if (ret < 0)
        {
          printf("kvdb: del %s failed: %d\n", argv[2], ret);
          return EXIT_FAILURE;
        }

      printf("kvdb: %s removed\n", argv[2]);
      return EXIT_SUCCESS;
    }

  kvdb_usage();
  return EXIT_FAILURE;
}

