int bk7258_kvdb_init(void)
{
  FAR struct kvdb_header_s *hdr;
  int ret;

  nxmutex_lock(&g_kvdb_lock);

  if (g_kvdb_loaded)
    {
      nxmutex_unlock(&g_kvdb_lock);
      return OK;
    }

  if (g_kvdb_image == NULL)
    {
      g_kvdb_image = malloc(KVDB_CAPACITY);
      if (g_kvdb_image == NULL)
        {
          nxmutex_unlock(&g_kvdb_lock);
          return -ENOMEM;
        }
    }

#ifdef CONFIG_BK7258_KVDB_FLASH
  ret = bk7258_flash_client_init();
#else
  /* See CONFIG_BK7258_KVDB_FLASH: the flash request path is unfinished, so
   * the store is deliberately memory-only until it is.
   */

  ret = -ENOTSUP;
#endif
  if (ret < 0)
    {
      /* No flash service: start empty and in memory only, so a board whose
       * CP does not serve flash still runs -- it just forgets on reset, which
       * is the behaviour everything had before this existed.
       */

      kvdb_reset_image();
      g_kvdb_loaded = true;
      g_kvdb_persistent = false;
      nxmutex_unlock(&g_kvdb_lock);
      printf("kvdb: in-memory only%s\n",
             ret == -ENOTSUP ? " (flash backend disabled)" :
                               " (no flash service)");
      return ret;
    }

  ret = bk7258_flash_read(KVDB_SECTOR, g_kvdb_image, KVDB_CAPACITY);
  if (ret < 0)
    {
      kvdb_reset_image();
      g_kvdb_loaded = true;
      nxmutex_unlock(&g_kvdb_lock);
      printf("kvdb: read failed (%d), starting empty\n", ret);
      return ret;
    }

  hdr = kvdb_hdr();

  if (memcmp(hdr->magic, KVDB_MAGIC, KVDB_MAGIC_LEN) != 0 ||
      hdr->version != KVDB_VERSION ||
      hdr->bytes > KVDB_CAPACITY - sizeof(struct kvdb_header_s) ||
      hdr->crc != kvdb_crc32(kvdb_records(), hdr->bytes))
    {
      printf("kvdb: no valid store at 0x%08x, starting empty\n",
             (unsigned int)KVDB_SECTOR);
      kvdb_reset_image();
    }
  else
    {
      printf("kvdb: %lu key(s) loaded from flash, %lu bytes used\n",
             (unsigned long)hdr->count, (unsigned long)hdr->bytes);
    }

  g_kvdb_loaded = true;
  g_kvdb_persistent = true;
  nxmutex_unlock(&g_kvdb_lock);
  return OK;
}

